# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİZİKSEL VE KİMYASAL DEĞİŞİMDE TANECİK YAPISI (F.8.4.2.1)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Fiziksel Değişim (Dış Görünüş)</text>\n  <!-- Molekül çizimi: H2O hal değişimi -->\n  <circle cx="80" cy="115" r="10" fill="#ef4444"/><circle cx="68" cy="127" r="6" fill="#3b82f6"/><circle cx="92" cy="127" r="6" fill="#3b82f6"/>\n  <circle cx="115" cy="115" r="10" fill="#ef4444"/><circle cx="103" cy="127" r="6" fill="#3b82f6"/><circle cx="127" cy="127" r="6" fill="#3b82f6"/>\n  <text x="175" y="122" text-anchor="middle" font-size="16" font-weight="bold" fill="#1d4ed8">→</text>\n  <circle cx="235" cy="105" r="10" fill="#ef4444"/><circle cx="223" cy="117" r="6" fill="#3b82f6"/><circle cx="247" cy="117" r="6" fill="#3b82f6"/>\n  <circle cx="295" cy="125" r="10" fill="#ef4444"/><circle cx="283" cy="137" r="6" fill="#3b82f6"/><circle cx="307" cy="137" r="6" fill="#3b82f6"/>\n  <text x="180" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Maddenin kimliği (iç yapısı) DEĞİŞMEZ.</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#1e3a8a">• Yeni madde oluşmaz; tanecikler arası</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" fill="#1e3a8a">boşluk ve çekim kuvveti değişir.</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Örnek: Hâl değişimi, kırılma, çözünme</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Kimyasal Değişim (İç Yapı / Kimlik)</text>\n  <!-- Molekül çizimi: Bağ kırılması ve yeni bağ -->\n  <circle cx="415" cy="110" r="9" fill="#ef4444"/><circle cx="433" cy="110" r="9" fill="#ef4444"/>\n  <circle cx="465" cy="102" r="6" fill="#3b82f6"/><circle cx="477" cy="102" r="6" fill="#3b82f6"/>\n  <circle cx="465" cy="122" r="6" fill="#3b82f6"/><circle cx="477" cy="122" r="6" fill="#3b82f6"/>\n  <text x="515" y="118" text-anchor="middle" font-size="16" font-weight="bold" fill="#be123c">→</text>\n  <circle cx="570" cy="110" r="9" fill="#ef4444"/><circle cx="558" cy="122" r="6" fill="#3b82f6"/><circle cx="582" cy="122" r="6" fill="#3b82f6"/>\n  <circle cx="625" cy="110" r="9" fill="#ef4444"/><circle cx="613" cy="122" r="6" fill="#3b82f6"/><circle cx="637" cy="122" r="6" fill="#3b82f6"/>\n  <text x="520" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Maddenin kimliği (iç yapısı) DEĞİŞİR.</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#881337">• Atomlar arası bağlar kopar, yeni bağlar</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" fill="#881337">kurularak YENİ MADDE oluşur.</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Örnek: Yanma, paslanma, mayalanma, sindirim</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GÜNLÜK YAŞAMDAN FİZİKSEL VE KİMYASAL DEĞİŞİM ÖRNEKLERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Fiziksel Değişim Örnekleri</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#164e63">• Buzun erimesi, suyun buharlaşması, kırağı</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#164e63">• Şekerin veya tuzun suda çözünmesi</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#164e63">• Camın kırılması, kâğıdın yırtılması</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#164e63">• Yoğurttan ayran, sütten tereyağı yapılması</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#164e63">• Gökkuşağı oluşumu, ışığın kırılması</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#164e63">• Bakır telin elektriği ve ısıyı iletmesi</text>\n  <text x="180" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Naftalinin ve kuru buzun süblimleşmesi</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Kimyasal Değişim Örnekleri</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#713f12">• Kâğıdın, odunun, mumun fitilinin yanması</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#713f12">• Demirin paslanması, gümüşün kararması</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#713f12">• Sütten yoğurt/peynir, üzümden sirke yapımı</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" fill="#713f12">• Fotosentez, solunum ve besinlerin sindirimi</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#713f12">• Yumurtanın haşlanması, patatesin kızarması</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#713f12">• Meyve ve sebzelerin çürümesi, küflenmesi</text>\n  <text x="520" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• Karbonat + limon suyundan gaz çıkışı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KİMYASAL DEĞİŞİM İPUÇLARI VE PERİYODİK SİSTEM ÖZETİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kimyasal Değişimin Gözlemlenen Kanıtları</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" fill="#14532d">1. Gaz Çıkışı (Kabarcık oluşumu)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#14532d">2. Renk, Tat ve Koku Değişimi</text>\n  <text x="180" y="144" text-anchor="middle" font-size="11" fill="#14532d">3. Isı ve Işık Yayılması (Yanma vb.)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" fill="#14532d">4. Çökelti (Tortu) Oluşumu</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Sonuç: Kimyasal değişim süreci bir</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">KİMYASAL TEPKİME ile gerçekleşir.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Element Sınıfları ve Değişim İlişkisi</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" fill="#581c87">• Metaller: Tel ve levha hâline getirilebilir</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#581c87">(fiziksel), oksijenle paslanır (kimyasal).</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11" fill="#581c87">• Yarı Metaller: Fiziksel özellikleri metallere,</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" fill="#581c87">kimyasal özellikleri ametallere benzer (Bor, Si).</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11" fill="#581c87">• Soy Gazlar (8A): Kararlıdır, bağ yapmaz</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">(He: 2 elektronla 8A\'da yer alır!).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
